            $sql = "select * from estado where estado_tipo = 4";
            $data['estados'] = $this->Venta_model->consultar($sql);
            $data['cobros'] = $this->Venta_model->consultar($sql);

            $data['_view'] = 'credito/reporte_cobros';
            $this->load->view('layouts/main',$data);
        }
